```python
from fastapi import FastAPI
from pydantic import BaseModel

app = FastAPI()

class Item(BaseModel):
    name: str
    price: float

@app.get("/items/")
async def read_items():
    return [{"item_name": i.item_name, "item_price": i.item_price} for i in Item.items()]

# Def function
@app.get("/sync-item/")
def read_sync_item():
    return {"sync_item": "This is a sync function"}

